import logging, math, os

log = logging.getLogger("ml")
FRESHNESS = {"fresh": 0, "stale": 1, "missing": 2, "unavailable": 3}
# Order is part of the model contract; training must use exactly this order.
FEATURE_ORDER = ["count_5m", "amount_ratio", "new_device", "amount_minor", "freshness", "mcc"]


class Scorer:
    def __init__(self, path: str):
        self.model, self.version = None, "none"
        if not os.path.exists(path):
            log.warning("no model at %s; ML disabled, rules only", path)
            return
        try:
            import lightgbm as lgb
            self.model, self.version = lgb.Booster(model_file=path), os.path.basename(path)
            self.model.predict([[0.0] * len(FEATURE_ORDER)])        # warm-up call
        except Exception:
            self.model = None
            log.exception("model load failed; ML disabled")

    @staticmethod
    def _num(v) -> float:
        return math.nan if v is None else float(v)

    def vector(self, f, txn) -> list[float]:
        try:
            mcc = float(txn.merchant.mcc)
        except ValueError:
            mcc = math.nan
        return [f.count_5m, self._num(f.amount_ratio), self._num(f.new_device),
                f.amount_minor, FRESHNESS[f.freshness], mcc]

    def score(self, f, txn) -> float | None:
        if self.model is None:
            return None
        try:
            return float(self.model.predict([self.vector(f, txn)])[0])
        except Exception:
            log.exception("scoring failed")
            return None
